ee:variables.ee:set-variable:
%dw 2.0 import * from dw::core::Strings import * from dw::core::Arrays
var capitalizedPayloadArr = vars.inputPayload.data map(item, ind) -> item mapObject ((value, key, index) -> { (capitalize("$key")) : value}) var outputArr = outerJoin (vars.responseMongo[0].Comunicaciones_Cobranza.Registro_Contacto, capitalizedPayloadArr, (a) -> a.Canal, (b) -> b.Canal)
output application/json --- (outputArr map ((item, index) -> if (item.l? and item.r?) item.r else if (item.l?) item.l else item.r))

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
if (payload.matched == 1 and payload.modified == 1) {
	codigo: 200
}
else
{
  "status": 500,
  "code": "CONTACT_INFO",
  "message": {
    "message": "Unable to register contact information for that user"
  },
  "messageServer": "",
  "cause": [
    {
      "origin": app.name,
      "message": "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
    }
  ]
}

%dw 2.0
output application/json
---
{
  "status": 500,
  "code": "CONTACT_INFO",
  "message": {
    "message": "There is no contact information for that user"
  },
  "messageServer": "",
  "cause": [
    {
      "origin": app.name,
      "message": "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
    }
  ]
}
